macro_rules! deps {
    () => {
        Array!();
    };
}

macro_rules! ArrayVec {
    () => {
        deps!();
        # [doc = " An array-backed, vector-like data structure."] # [doc = ""] # [doc = " * `ArrayVec` has a fixed capacity, equal to the minimum of the array size"] # [doc = "   and `u16::MAX`. Note that not all capacities are necessarily supported by"] # [doc = "   default. See comments in [`Array`]."] # [doc = " * `ArrayVec` has a variable length, as you add and remove elements. Attempts"] # [doc = "   to fill the vec beyond its capacity will cause a panic."] # [doc = " * All of the vec's array slots are always initialized in terms of Rust's"] # [doc = "   memory model. When you remove a element from a location, the old value at"] # [doc = "   that location is replaced with the type's default value."] # [doc = ""] # [doc = " The overall API of this type is intended to, as much as possible, emulate"] # [doc = " the API of the [`Vec`](https://doc.rust-lang.org/alloc/vec/struct.Vec.html)"] # [doc = " type."] # [doc = ""] # [doc = " ## Construction"] # [doc = ""] # [doc = " You can use the `array_vec!` macro similarly to how you might use the `vec!`"] # [doc = " macro. Specify the array type, then optionally give all the initial values"] # [doc = " you want to have."] # [doc = " ```rust"] # [doc = " # use tinyvec::*;"] # [doc = " let some_ints = array_vec!([i32; 4] => 1, 2, 3);"] # [doc = " assert_eq!(some_ints.len(), 3);"] # [doc = " ```"] # [doc = ""] # [doc = " The [`default`](ArrayVec::new) for an `ArrayVec` is to have a default"] # [doc = " array with length 0. The [`new`](ArrayVec::new) method is the same as"] # [doc = " calling `default`"] # [doc = " ```rust"] # [doc = " # use tinyvec::*;"] # [doc = " let some_ints = ArrayVec::<[i32; 7]>::default();"] # [doc = " assert_eq!(some_ints.len(), 0);"] # [doc = ""] # [doc = " let more_ints = ArrayVec::<[i32; 7]>::new();"] # [doc = " assert_eq!(some_ints, more_ints);"] # [doc = " ```"] # [doc = ""] # [doc = " If you have an array and want the _whole thing_ so count as being \"in\" the"] # [doc = " new `ArrayVec` you can use one of the `from` implementations. If you want"] # [doc = " _part of_ the array then you can use"] # [doc = " [`from_array_len`](ArrayVec::from_array_len):"] # [doc = " ```rust"] # [doc = " # use tinyvec::*;"] # [doc = " let some_ints = ArrayVec::from([5, 6, 7, 8]);"] # [doc = " assert_eq!(some_ints.len(), 4);"] # [doc = ""] # [doc = " let more_ints = ArrayVec::from_array_len([5, 6, 7, 8], 2);"] # [doc = " assert_eq!(more_ints.len(), 2);"] # [doc = ""] # [doc = " let no_ints: ArrayVec<[u8; 5]> = ArrayVec::from_array_empty([1, 2, 3, 4, 5]);"] # [doc = " assert_eq!(no_ints.len(), 0);"] # [doc = " ```"] # [repr (C)] pub struct ArrayVec < A > { len : u16 , pub (crate) data : A , }
    };
}

ArrayVec!()